command:
if (!game.user.isGM) return ui.notifications.warn('Restore All Units (Scene) is GM-only.');

const scene = canvas.scene;
if (!scene) return ui.notifications.warn('No map is active.');
const placed = scene.tokens.filter(token => token.actor?.type === 'Character').length;
if (!placed) return ui.notifications.warn(`No units are placed on ${scene.name}.`);
const reachLabel = `every unit on ${scene.name}`;

const proceed = await foundry.applications.api.DialogV2.wait({
  window: { title: 'Restore All Units (Scene)' },
  classes: ['emblem-rpg', 'dialog-editor'],
  position: { width: 460 },
  content: `
    <div class="ed-container">
      <div class="ed-section ed-section--highlight">
        <p class="ed-description">Fully restore ${reachLabel}?</p>
      </div>
      <div class="ed-section">
        <p class="ed-description">Every unit in reach is set back to its maximum resources and a fresh turn.
          All temporary active effects are dispelled, leaving wielded, mounted and armor
          effects intact, and every item they carry that Refreshes is returned to full uses.</p>
      </div>
    </div>`,
  buttons: [
    { action: 'confirm', label: 'Restore', icon: 'fas fa-heart', callback: () => true },
    { action: 'cancel', label: 'Cancel', default: true, callback: () => false }
  ],
  rejectClose: false
});
if (!proceed) return;

const result = await game.emblemRpg.api.development.restoreUnits({ scope: 'scene', sceneUuid: scene.uuid });

console.group(`emblem-rpg | Restore All Units (Scene) — ${result.ok ? 'settled' : 'refused'}`);
console.log(result.ok ? result.data : result);
console.groupEnd();
